import { cva } from "class-variance-authority";
import * as React from "react";
import { cn } from "../../lib/utils.js";

type TimelineStatus = "default" | "success" | "warning" | "error" | "info";

interface TimelineEvent {
	/** Stable unique id used as the React key. */
	id: string;
	/** Headline for the event. */
	title: string;
	/** Optional timestamp/metadata (e.g. "2 hours ago", "2026-04-27 14:30"). */
	timestamp?: React.ReactNode;
	/** Optional secondary text/body. */
	description?: React.ReactNode;
	/** Optional icon override for the indicator. Replaces the default dot. */
	icon?: React.ReactNode;
	/** Color variant for the indicator. */
	status?: TimelineStatus;
}

/*
 * `warning` uses a token-with-fallback so themes can override `--color-warning`
 * without touching component source. The OKLCH default lands at a desaturated
 * amber that holds AA contrast on both light and dark backgrounds.
 */
const indicator = cva(
	"relative z-10 inline-flex shrink-0 items-center justify-center rounded-full border-2 transition-colors duration-[var(--duration-normal,200ms)] ease-out",
	{
		variants: {
			status: {
				default: "bg-background border-input text-muted-foreground",
				success: "bg-background border-primary text-primary",
				warning:
					"bg-background border-[var(--color-warning,oklch(0.78_0.16_82))] text-[var(--color-warning,oklch(0.78_0.16_82))]",
				error: "bg-destructive border-destructive text-destructive-foreground",
				info: "bg-background border-ring text-ring",
			},
			size: {
				sm: "h-5 w-5 text-[10px]",
				md: "h-7 w-7 text-xs",
			},
		},
		defaultVariants: { status: "default", size: "md" },
	},
);

interface TimelineProps
	extends Omit<React.HTMLAttributes<HTMLOListElement>, "aria-label"> {
	/** Ordered list of chronological events. */
	events: TimelineEvent[];
	/** Indicator size — `"md"` by default. */
	size?: "sm" | "md";
	/** Required accessible name for the ordered list. */
	"aria-label": string;
}

/** Solid dot rendered inside the indicator when no per-event icon is supplied. */
function DefaultDot() {
	return <span className="h-1.5 w-1.5 rounded-full bg-current" aria-hidden="true" />;
}

/**
 * Vertical chronological event feed (activity log, audit trail, release notes).
 * Pure semantic HTML — `<ol>` of `<li>`. Events expose an optional icon, a
 * status color, a timestamp, and a description; status is purely visual, no
 * aria-current is set since events are historical, not navigational.
 *
 * For Gantt-style project timelines, build a custom layout — Timeline is for
 * event feeds, not scheduling.
 * @returns An accessible vertical event list.
 */
function Timeline({
	events,
	size = "md",
	"aria-label": ariaLabel,
	className,
	...rest
}: TimelineProps) {
	return (
		<ol
			aria-label={ariaLabel}
			className={cn("flex flex-col list-none p-0 m-0", className)}
			{...rest}
		>
			{events.map((event, index) => {
				const isLast = index === events.length - 1;
				const status = event.status ?? "default";
				return (
					<li key={event.id} className="relative flex gap-[var(--space-3,0.75rem)]">
						<div className="flex flex-col items-center">
							<span className={indicator({ status, size })}>
								{event.icon ?? <DefaultDot />}
							</span>
							{!isLast ? (
								<span
									aria-hidden="true"
									className="w-px flex-1 bg-input min-h-[var(--space-6,1.5rem)]"
								/>
							) : null}
						</div>
						<div
							className={cn(
								"flex flex-col gap-[var(--space-1,0.25rem)] min-w-0",
								!isLast && "pb-[var(--space-6,1.5rem)]",
							)}
						>
							<div className="flex flex-wrap items-baseline gap-[var(--space-2,0.5rem)]">
								<span className="text-sm font-medium text-foreground">
									{event.title}
								</span>
								{event.timestamp ? (
									<span className="text-xs text-muted-foreground">
										{event.timestamp}
									</span>
								) : null}
							</div>
							{event.description ? (
								<div className="text-sm text-muted-foreground">
									{event.description}
								</div>
							) : null}
						</div>
					</li>
				);
			})}
		</ol>
	);
}
Timeline.displayName = "Timeline";

export { Timeline };
export type { TimelineEvent, TimelineProps, TimelineStatus };

/**
 * Color conversion utilities for the HSL-triplet token format used across
 * `@hex-core/tokens` themes (`H S% L%`, e.g. `"240 5.9% 10%"` — no `hsl()`
 * wrapper, no commas).
 *
 * The triplet is the round-trip-safe serialization for Hex UI: tokens flow
 * triplet → CSS `hsl(var(--token))` → rendered color, and the ColorPicker
 * component edits triplets directly. Hex/RGB conversions are display
 * adapters, not the source of truth.
 */

/** Parsed HSL components. `h` is degrees (0–360); `s` and `l` are percentages (0–100). */
export interface HslTriplet {
	h: number;
	s: number;
	l: number;
}

/** Parsed RGB components. Each channel is 0–255. */
export interface RgbColor {
	r: number;
	g: number;
	b: number;
}

/**
 * Parse an HSL triplet string into numeric components.
 *
 * Note: malformed input silently coerces to `{0,0,0}` (pure black) rather than
 * returning an error signal. Callers that need to distinguish "user typed
 * black" from "user typed garbage" should validate the input format first.
 * `hexToHslTriplet` returns `null` for malformed hex; this asymmetry is
 * intentional — triplets feed CSS variables where any non-color value would
 * already break rendering.
 *
 * @param triplet - String in the form `"<H> <S>% <L>%"` (e.g. `"240 5.9% 10%"`).
 * @returns Numeric components, or `{0,0,0}` if the input is malformed.
 */
export function parseHslTriplet(triplet: string): HslTriplet {
	const parts = triplet.trim().split(/\s+/);
	return {
		h: Number.parseFloat(parts[0]) || 0,
		s: Number.parseFloat(parts[1]) || 0,
		l: Number.parseFloat(parts[2]) || 0,
	};
}

/**
 * Format HSL components into an HSL triplet string (the canonical token format).
 * @param hsl - Numeric components.
 * @returns Triplet in the form `"<H> <S>% <L>%"`.
 */
export function formatHslTriplet({ h, s, l }: HslTriplet): string {
	// Tolerant integer check: rgbToHsl can produce values like 5.0000000001 due
	// to float arithmetic; format those as "5" rather than "5.0".
	const round = (n: number) =>
		Math.abs(n - Math.round(n)) < 1e-6 ? `${Math.round(n)}` : n.toFixed(1);
	return `${Math.round(h)} ${round(s)}% ${round(l)}%`;
}

/**
 * Convert HSL components to RGB.
 * @param h - Hue (0–360).
 * @param s - Saturation (0–100).
 * @param l - Lightness (0–100).
 * @returns RGB channels (0–255, rounded).
 */
export function hslToRgb(h: number, s: number, l: number): RgbColor {
	const sN = s / 100;
	const lN = l / 100;
	const k = (n: number) => (n + h / 30) % 12;
	const a = sN * Math.min(lN, 1 - lN);
	const f = (n: number) => lN - a * Math.max(-1, Math.min(k(n) - 3, 9 - k(n), 1));
	return {
		r: Math.round(255 * f(0)),
		g: Math.round(255 * f(8)),
		b: Math.round(255 * f(4)),
	};
}

/**
 * Convert RGB components to HSL.
 * @param r - Red (0–255).
 * @param g - Green (0–255).
 * @param b - Blue (0–255).
 * @returns HSL components (h: 0–360, s: 0–100, l: 0–100).
 */
export function rgbToHsl(r: number, g: number, b: number): HslTriplet {
	const rN = r / 255;
	const gN = g / 255;
	const bN = b / 255;
	const max = Math.max(rN, gN, bN);
	const min = Math.min(rN, gN, bN);
	let h = 0;
	let s = 0;
	const l = (max + min) / 2;
	if (max !== min) {
		const d = max - min;
		s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
		if (max === rN) h = (gN - bN) / d + (gN < bN ? 6 : 0);
		else if (max === gN) h = (bN - rN) / d + 2;
		else h = (rN - gN) / d + 4;
		h /= 6;
	}
	return { h: h * 360, s: s * 100, l: l * 100 };
}

/**
 * Convert an HSL triplet to a 6-digit hex string.
 * @param triplet - HSL triplet (e.g. `"240 5.9% 10%"`).
 * @returns Lowercase hex string with leading `#` (e.g. `"#181a1f"`).
 */
export function hslTripletToHex(triplet: string): string {
	const { h, s, l } = parseHslTriplet(triplet);
	const { r, g, b } = hslToRgb(h, s, l);
	const toHex = (n: number) => n.toString(16).padStart(2, "0");
	return `#${toHex(r)}${toHex(g)}${toHex(b)}`;
}

/**
 * Convert a hex string to an HSL triplet.
 * Accepts 3-digit (`#abc`) or 6-digit (`#aabbcc`) hex with optional `#`.
 * @param hex - Hex color string.
 * @returns HSL triplet, or `null` if the input is malformed.
 */
export function hexToHslTriplet(hex: string): string | null {
	const clean = hex.trim().replace(/^#/, "");
	let normalized: string;
	if (/^[0-9a-fA-F]{3}$/.test(clean)) {
		normalized = clean
			.split("")
			.map((c) => c + c)
			.join("");
	} else if (/^[0-9a-fA-F]{6}$/.test(clean)) {
		normalized = clean;
	} else {
		return null;
	}
	const r = Number.parseInt(normalized.slice(0, 2), 16);
	const g = Number.parseInt(normalized.slice(2, 4), 16);
	const b = Number.parseInt(normalized.slice(4, 6), 16);
	return formatHslTriplet(rgbToHsl(r, g, b));
}

import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

/**
 * Merge class names with Tailwind CSS conflict resolution.
 * @param inputs - Class values (strings, arrays, objects) to merge
 * @returns A single merged class string with Tailwind conflicts resolved
 */
export function cn(...inputs: ClassValue[]) {
	return twMerge(clsx(inputs));
}

